-- SOURCE replace_draft.sql sha256=8b07514a15acb51727f66558ad8d77cf12a4e2d5974e97257229dd027d47d00a
-- The 20261107 draft created transfer tables that no code path could write to:
-- every insert referenced columns those tables never defined. Remove them only
-- while they are still empty so that no recorded data can be lost silently.
DO $$
DECLARE relation_name text; has_rows boolean;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY['transfer_request_actions', 'transfer_requests',
        'student_academic_placements', 'subject_equivalencies', 'institution_transfer_settings'] LOOP
        IF to_regclass(format('public.%I', relation_name)) IS NOT NULL THEN
            EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I)', relation_name) INTO has_rows;
            IF has_rows THEN
                RAISE EXCEPTION 'Draft transfer table public.% contains rows; inspect it before migrating',
                    relation_name;
            END IF;
            EXECUTE format('DROP TABLE public.%I', relation_name);
        END IF;
    END LOOP;
END;
$$;

-- SOURCE tables.sql sha256=0399e88633797efc125d71f467d8c52e3830da8cd1cf5417aeaa3b2ac84f84f2
-- One current Head of Department per department. Ended appointments are kept
-- as history; a new appointment never rewrites an earlier row.
CREATE TABLE public.department_heads (
    department_head_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id),
    department_id uuid NOT NULL,
    faculty_user_id uuid NOT NULL REFERENCES public.users(id),
    assigned_by uuid NOT NULL REFERENCES public.users(id),
    assigned_at timestamptz NOT NULL DEFAULT now(),
    ended_by uuid REFERENCES public.users(id),
    ended_at timestamptz,
    FOREIGN KEY (department_id, institution_id)
        REFERENCES public.departments(department_id, institution_id),
    CONSTRAINT department_heads_end_pair CHECK ((ended_at IS NULL) = (ended_by IS NULL))
);
CREATE UNIQUE INDEX department_heads_one_current
    ON public.department_heads (department_id) WHERE ended_at IS NULL;
CREATE INDEX department_heads_faculty
    ON public.department_heads (institution_id, faculty_user_id) WHERE ended_at IS NULL;

-- A request moves one current-term semester registration to another section.
-- The from/to sections and the pre-transfer registration are retained as the
-- student's placement history after approval.
CREATE TABLE public.student_transfer_requests (
    transfer_request_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id),
    student_id uuid NOT NULL REFERENCES public.students(student_id),
    transfer_type text NOT NULL CHECK (transfer_type IN ('section_transfer', 'program_transfer')),
    semester_registration_id uuid NOT NULL,
    semester_id uuid NOT NULL REFERENCES public.semesters(semester_id),
    from_section_id uuid NOT NULL,
    to_section_id uuid NOT NULL,
    from_program_id uuid NOT NULL,
    to_program_id uuid NOT NULL,
    to_department_id uuid NOT NULL,
    reason text NOT NULL CHECK (length(btrim(reason)) BETWEEN 10 AND 2000),
    status text NOT NULL DEFAULT 'submitted'
        CHECK (status IN ('submitted', 'under_review', 'approved', 'rejected', 'cancelled')),
    submitted_by uuid NOT NULL REFERENCES public.users(id),
    submitted_at timestamptz NOT NULL DEFAULT now(),
    review_started_by uuid REFERENCES public.users(id),
    review_started_at timestamptz,
    decided_by uuid REFERENCES public.users(id),
    decided_at timestamptz,
    decided_as text CHECK (decided_as IN ('admin', 'hod')),
    decision_comment text CHECK (length(decision_comment) <= 2000),
    cancelled_at timestamptz,
    previous_registration jsonb,
    previous_enrollments jsonb NOT NULL DEFAULT '[]'::jsonb,
    updated_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (transfer_request_id, institution_id),
    FOREIGN KEY (semester_registration_id, institution_id)
        REFERENCES public.student_semester_registrations(semester_registration_id, institution_id),
    FOREIGN KEY (from_section_id, institution_id)
        REFERENCES public.academic_sections(academic_section_id, institution_id),
    FOREIGN KEY (to_section_id, institution_id)
        REFERENCES public.academic_sections(academic_section_id, institution_id),
    FOREIGN KEY (from_program_id, institution_id) REFERENCES public.programs(program_id, institution_id),
    FOREIGN KEY (to_program_id, institution_id) REFERENCES public.programs(program_id, institution_id),
    FOREIGN KEY (to_department_id, institution_id)
        REFERENCES public.departments(department_id, institution_id),
    CONSTRAINT student_transfer_distinct_section CHECK (from_section_id <> to_section_id),
    CONSTRAINT student_transfer_decision CHECK (
        (status IN ('approved', 'rejected'))
        = (decided_at IS NOT NULL AND decided_by IS NOT NULL AND decided_as IS NOT NULL)),
    CONSTRAINT student_transfer_rejection_reason CHECK (
        status <> 'rejected' OR length(btrim(COALESCE(decision_comment, ''))) > 0),
    CONSTRAINT student_transfer_cancelled CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL))
);
CREATE UNIQUE INDEX student_transfer_one_open
    ON public.student_transfer_requests (student_id) WHERE status IN ('submitted', 'under_review');
CREATE INDEX student_transfer_queue
    ON public.student_transfer_requests (institution_id, status, submitted_at DESC);
CREATE INDEX student_transfer_department
    ON public.student_transfer_requests (institution_id, to_department_id, status);

CREATE TABLE public.student_transfer_events (
    transfer_event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL,
    transfer_request_id uuid NOT NULL,
    actor_user_id uuid NOT NULL REFERENCES public.users(id),
    action text NOT NULL
        CHECK (action IN ('submitted', 'review_started', 'approved', 'rejected', 'cancelled')),
    comment text CHECK (length(comment) <= 2000),
    created_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (transfer_request_id, institution_id)
        REFERENCES public.student_transfer_requests(transfer_request_id, institution_id)
);
CREATE INDEX student_transfer_events_request
    ON public.student_transfer_events (transfer_request_id, created_at);

COMMENT ON TABLE public.department_heads IS
    'Current and ended Head of Department appointments; HODs decide transfers into their department.';
COMMENT ON TABLE public.student_transfer_requests IS
    'Student section and program transfer requests. Approval reassigns the current-term registration.';
COMMENT ON TABLE public.student_transfer_events IS
    'Append-only history of submission, review, decision and cancellation for each transfer request.';

-- SOURCE permissions.sql sha256=376a4cf5989e8892c9192fe254ad39f44a3d52de0a3b77fc66c2b83d729437d2
-- Students request and read their own transfers. Institution administrators
-- read and decide every transfer. Heads of Department receive no role grant:
-- their authority comes only from a current department_heads appointment.
INSERT INTO public.permissions (code, name, description, scope, is_active)
VALUES
    ('transfers.request', 'Request academic transfer',
        'Submit and cancel own section or program transfer requests', 'institution', true),
    ('transfers.read', 'Read academic transfers', 'View academic transfer requests', 'institution', true),
    ('transfers.approve', 'Decide academic transfers',
        'Review, approve and reject academic transfer requests', 'institution', true)
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    scope = 'institution', is_active = true, updated_at = now();

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.permission_id
FROM public.roles r CROSS JOIN public.permissions p
WHERE (r.name = 'student' AND p.code IN ('transfers.request', 'transfers.read'))
   OR (r.name = 'admin' AND p.code IN ('transfers.read', 'transfers.approve'))
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- SOURCE authorization.sql sha256=91a423a7ea1c0e8e0058287219a4801091f99bf4864e6120ed96dfa17859db0b
-- Every transfer command is called by the trusted backend with the
-- authenticated actor. Authority is re-derived here from current grants.
CREATE FUNCTION public.assert_transfer_backend()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
END;
$$;

-- Exact institution-scoped administrator grant with an active tenant.
CREATE FUNCTION public.transfer_admin_allowed(p_actor uuid, p_tenant uuid, p_permission text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.users u
        JOIN public.user_roles ur ON ur.user_id = u.id
        JOIN public.roles r ON r.id = ur.role_id
        JOIN public.role_permissions rp ON rp.role_id = r.id
        JOIN public.permissions p ON p.permission_id = rp.permission_id
        JOIN public.institutions i ON i.institution_id = p_tenant
        JOIN public.organizations org ON org.organization_id = i.organization_id
        WHERE u.id = p_actor AND u.status = 'active' AND r.name = 'admin' AND r.is_active
          AND ur.scope_type = 'institution' AND ur.scope_id = p_tenant
          AND ur.scope_organization_id = i.organization_id
          AND i.is_active AND i.status = 'active' AND org.status = 'active'
          AND p.is_active AND p.scope IN ('institution', 'global')
          AND p.code IN (p_permission, split_part(p_permission, '.', 1) || '.*', '*')
    );
$$;

-- An HOD must still be an active faculty member of the same institution.
CREATE FUNCTION public.transfer_is_active_faculty(p_user uuid, p_tenant uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT EXISTS (
        SELECT 1
        FROM public.users u
        JOIN public.user_roles ur ON ur.user_id = u.id
        JOIN public.roles r ON r.id = ur.role_id
        JOIN public.institutions i ON i.institution_id = p_tenant
        JOIN public.organizations org ON org.organization_id = i.organization_id
        WHERE u.id = p_user AND u.status = 'active' AND r.name = 'faculty' AND r.is_active
          AND ur.scope_type = 'institution' AND ur.scope_id = p_tenant
          AND ur.scope_organization_id = i.organization_id
          AND i.is_active AND i.status = 'active' AND org.status = 'active'
    );
$$;

-- Active departments the actor currently heads. Empty for everyone else.
CREATE FUNCTION public.transfer_hod_departments(p_actor uuid, p_tenant uuid)
RETURNS uuid[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT COALESCE(array_agg(h.department_id ORDER BY h.department_id), '{}'::uuid[])
    FROM public.department_heads h
    JOIN public.departments d
        ON d.department_id = h.department_id AND d.institution_id = p_tenant AND d.is_active
    WHERE h.institution_id = p_tenant AND h.faculty_user_id = p_actor AND h.ended_at IS NULL
      AND public.transfer_is_active_faculty(p_actor, p_tenant);
$$;

-- Resolves the actor's own approved, active student record. A browser can
-- never name another student because the identity is derived from the actor.
CREATE FUNCTION public.assert_transfer_student(p_actor uuid, p_tenant uuid, p_permission text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_student uuid;
BEGIN
    PERFORM public.assert_transfer_backend();
    SELECT s.student_id INTO v_student
    FROM public.students s
    JOIN public.users u ON u.id = s.user_id
    JOIN public.institutions i ON i.institution_id = s.institution_id
    JOIN public.organizations org ON org.organization_id = i.organization_id
    JOIN public.user_roles ur ON ur.user_id = u.id
    JOIN public.roles r ON r.id = ur.role_id
    JOIN public.role_permissions rp ON rp.role_id = r.id
    JOIN public.permissions p ON p.permission_id = rp.permission_id
    WHERE u.id = p_actor AND u.status = 'active' AND s.institution_id = p_tenant
      AND s.is_active AND s.status = 'active' AND s.approval_status = 'approved'
      AND i.is_active AND i.status = 'active' AND org.status = 'active'
      AND r.name = 'student' AND r.is_active AND ur.scope_type = 'institution'
      AND ur.scope_id = p_tenant AND ur.scope_organization_id = i.organization_id
      AND p.is_active AND p.scope = 'institution'
      AND p.code IN (p_permission, 'transfers.*', '*')
    LIMIT 1
    FOR SHARE OF s;
    IF v_student IS NULL THEN
        RAISE EXCEPTION 'Approved student with transfer permission required' USING ERRCODE = '42501';
    END IF;
    RETURN v_student;
END;
$$;

-- The student's current placement: the registration in the latest term,
-- matching the ordering used by the student directory.
CREATE FUNCTION public.transfer_current_registration(p_student uuid, p_tenant uuid)
RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT registration.semester_registration_id
    FROM public.student_semester_registrations registration
    JOIN public.semesters term ON term.semester_id = registration.semester_id
    WHERE registration.student_id = p_student AND registration.institution_id = p_tenant
    ORDER BY term.start_date DESC, registration.assigned_at DESC, registration.semester_registration_id
    LIMIT 1;
$$;

-- SOURCE placement.sql sha256=ddbfb27012aa84ad1ee665207f1c0d661ba98a9d3474dafa6ebde49d91585aa3
-- Display and availability details for one tenant section.
CREATE FUNCTION public.transfer_section_json(p_section uuid, p_tenant uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT jsonb_build_object(
        'academic_section_id', sec.academic_section_id,
        'section_name', sec.name, 'section_code', sec.code,
        'admission_cohort_id', cohort.admission_cohort_id, 'batch_name', cohort.name,
        'program_id', program.program_id, 'program_name', program.name, 'program_code', program.code,
        'department_id', department.department_id, 'department_name', department.name,
        'program_semester_name', stage.name,
        'semester_id', term.semester_id, 'term_name', term.name,
        'capacity', sec.capacity,
        'seats_taken', (
            SELECT count(*) FROM public.student_semester_registrations taken
            WHERE taken.academic_section_id = sec.academic_section_id
        )
    )
    FROM public.academic_sections sec
    JOIN public.admission_cohorts cohort ON cohort.admission_cohort_id = sec.admission_cohort_id
    JOIN public.programs program ON program.program_id = cohort.program_id
    JOIN public.departments department ON department.department_id = program.department_id
    JOIN public.program_semesters stage ON stage.program_semester_id = sec.program_semester_id
    JOIN public.semesters term ON term.semester_id = sec.semester_id
    WHERE sec.academic_section_id = p_section AND sec.institution_id = p_tenant;
$$;

-- Classifies a move between two sections of the same open term, or returns
-- NULL when the move is not allowed. A section transfer stays in the same
-- batch; a program transfer moves to a different program. Moving to another
-- batch of the same program is not a transfer handled by this workflow.
CREATE FUNCTION public.transfer_target_type(p_from uuid, p_to uuid, p_tenant uuid)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT CASE
        WHEN target.admission_cohort_id = source.admission_cohort_id THEN 'section_transfer'
        WHEN target_cohort.program_id <> source_cohort.program_id THEN 'program_transfer'
    END
    FROM public.academic_sections source
    JOIN public.admission_cohorts source_cohort
        ON source_cohort.admission_cohort_id = source.admission_cohort_id
    JOIN public.academic_sections target
        ON target.academic_section_id = p_to AND target.institution_id = p_tenant
    JOIN public.admission_cohorts target_cohort
        ON target_cohort.admission_cohort_id = target.admission_cohort_id
    JOIN public.programs program ON program.program_id = target_cohort.program_id
    JOIN public.departments department ON department.department_id = program.department_id
    JOIN public.program_semesters stage ON stage.program_semester_id = target.program_semester_id
    JOIN public.semesters term ON term.semester_id = target.semester_id
    WHERE source.academic_section_id = p_from AND source.institution_id = p_tenant
      AND target.academic_section_id <> source.academic_section_id
      AND target.semester_id = source.semester_id
      AND target.is_active AND target_cohort.is_active AND program.is_active
      AND department.is_active AND stage.is_active AND term.is_active
      AND term.end_date >= current_date;
$$;

-- True while the section has no capacity limit or still has a free seat.
CREATE FUNCTION public.transfer_section_has_seat(p_section uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT sec.capacity IS NULL OR (
        SELECT count(*) FROM public.student_semester_registrations taken
        WHERE taken.academic_section_id = sec.academic_section_id
    ) < sec.capacity
    FROM public.academic_sections sec
    WHERE sec.academic_section_id = p_section;
$$;

-- Requests visible to one student (p_student) or to reviewers limited to the
-- given departments (NULL means every department, used for administrators).
CREATE FUNCTION public.transfer_requests_json(
    p_tenant uuid, p_student uuid, p_departments uuid[], p_open_only boolean
) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'transfer_request_id', t.transfer_request_id, 'student_id', t.student_id,
        'student_name', COALESCE(NULLIF(btrim(u.display_name), ''),
            NULLIF(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email),
        'register_number', COALESCE(s.register_number, s.student_number),
        'transfer_type', t.transfer_type, 'status', t.status, 'reason', t.reason,
        'from_section', public.transfer_section_json(t.from_section_id, p_tenant),
        'to_section', public.transfer_section_json(t.to_section_id, p_tenant),
        'submitted_at', t.submitted_at, 'review_started_at', t.review_started_at,
        'decided_at', t.decided_at, 'decided_as', t.decided_as,
        'decision_comment', t.decision_comment, 'cancelled_at', t.cancelled_at,
        'previous_enrollments', t.previous_enrollments,
        'events', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'action', e.action, 'comment', e.comment, 'created_at', e.created_at
            ) ORDER BY e.created_at, e.transfer_event_id), '[]'::jsonb)
            FROM public.student_transfer_events e
            WHERE e.transfer_request_id = t.transfer_request_id
        )
    ) ORDER BY t.submitted_at DESC, t.transfer_request_id), '[]'::jsonb)
    FROM public.student_transfer_requests t
    JOIN public.students s ON s.student_id = t.student_id
    LEFT JOIN public.users u ON u.id = s.user_id
    WHERE t.institution_id = p_tenant
      AND (p_student IS NULL OR t.student_id = p_student)
      AND (p_departments IS NULL OR t.to_department_id = ANY (p_departments))
      AND (NOT p_open_only OR t.status IN ('submitted', 'under_review'));
$$;

-- SOURCE student.sql sha256=c295688813c435f8174bcaab9457d25fdd8cb6f5c380fee620418693f854eeb4
-- The student's current placement, the sections they may request and their
-- own request history. No other student's data is reachable from here.
CREATE FUNCTION public.read_student_transfers(p_actor uuid, p_tenant uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_student uuid; v_registration public.student_semester_registrations;
    v_term public.semesters; v_open boolean;
BEGIN
    v_student := public.assert_transfer_student(p_actor, p_tenant, 'transfers.read');
    SELECT * INTO v_registration FROM public.student_semester_registrations
    WHERE semester_registration_id = public.transfer_current_registration(v_student, p_tenant);
    IF v_registration.semester_registration_id IS NULL THEN
        RETURN jsonb_build_object('institution_id', p_tenant, 'current', NULL,
            'options', '[]'::jsonb,
            'requests', public.transfer_requests_json(p_tenant, v_student, NULL, false));
    END IF;
    SELECT * INTO v_term FROM public.semesters WHERE semester_id = v_registration.semester_id;
    v_open := v_term.is_active AND v_term.end_date >= current_date;
    RETURN jsonb_build_object(
        'institution_id', p_tenant,
        'current', public.transfer_section_json(v_registration.academic_section_id, p_tenant)
            || jsonb_build_object(
                'semester_registration_id', v_registration.semester_registration_id,
                'registration_status', v_registration.status,
                'term_end_date', v_term.end_date, 'term_open', v_open),
        'options', CASE WHEN NOT v_open THEN '[]'::jsonb ELSE (
            SELECT COALESCE(jsonb_agg(option_row ORDER BY option_row->>'program_name',
                option_row->>'section_name', option_row->>'academic_section_id'), '[]'::jsonb)
            FROM (
                SELECT public.transfer_section_json(target.academic_section_id, p_tenant)
                    || jsonb_build_object(
                        'transfer_type', public.transfer_target_type(
                            v_registration.academic_section_id, target.academic_section_id, p_tenant),
                        'has_seat', public.transfer_section_has_seat(target.academic_section_id)
                    ) AS option_row
                FROM public.academic_sections target
                WHERE target.institution_id = p_tenant
                  AND target.semester_id = v_registration.semester_id
                  AND public.transfer_target_type(
                      v_registration.academic_section_id, target.academic_section_id, p_tenant) IS NOT NULL
            ) option_rows
        ) END,
        'requests', public.transfer_requests_json(p_tenant, v_student, NULL, false)
    );
END;
$$;

CREATE FUNCTION public.submit_student_transfer(
    p_actor uuid, p_tenant uuid, p_to_section uuid, p_reason text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_student uuid; v_registration public.student_semester_registrations; v_kind text;
    v_source jsonb; v_target jsonb; v_request public.student_transfer_requests;
BEGIN
    v_student := public.assert_transfer_student(p_actor, p_tenant, 'transfers.request');
    IF length(btrim(COALESCE(p_reason, ''))) NOT BETWEEN 10 AND 2000 THEN
        RAISE EXCEPTION 'Explain the transfer in 10 to 2000 characters' USING ERRCODE = 'P1108';
    END IF;
    -- Same tenant lock as section assignment, so seat counts cannot race.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:' || p_tenant::text, 0));
    IF EXISTS (SELECT 1 FROM public.student_transfer_requests
               WHERE student_id = v_student AND status IN ('submitted', 'under_review')) THEN
        RAISE EXCEPTION 'An open transfer request already exists' USING ERRCODE = 'P1106';
    END IF;
    SELECT * INTO v_registration FROM public.student_semester_registrations
    WHERE semester_registration_id = public.transfer_current_registration(v_student, p_tenant)
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'The student has no current section' USING ERRCODE = 'P1107';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.semesters WHERE semester_id = v_registration.semester_id
                   AND is_active AND end_date >= current_date) THEN
        RAISE EXCEPTION 'The current term is closed' USING ERRCODE = 'P1103';
    END IF;
    v_kind := public.transfer_target_type(v_registration.academic_section_id, p_to_section, p_tenant);
    IF v_kind IS NULL THEN
        RAISE EXCEPTION 'The requested section is unavailable' USING ERRCODE = 'P1104';
    END IF;
    IF NOT public.transfer_section_has_seat(p_to_section) THEN
        RAISE EXCEPTION 'The requested section is full' USING ERRCODE = 'P1105';
    END IF;
    v_source := public.transfer_section_json(v_registration.academic_section_id, p_tenant);
    v_target := public.transfer_section_json(p_to_section, p_tenant);
    INSERT INTO public.student_transfer_requests (
        institution_id, student_id, transfer_type, semester_registration_id, semester_id,
        from_section_id, to_section_id, from_program_id, to_program_id, to_department_id,
        reason, submitted_by)
    VALUES (p_tenant, v_student, v_kind, v_registration.semester_registration_id,
        v_registration.semester_id, v_registration.academic_section_id, p_to_section,
        (v_source->>'program_id')::uuid, (v_target->>'program_id')::uuid,
        (v_target->>'department_id')::uuid, btrim(p_reason), p_actor)
    RETURNING * INTO v_request;
    INSERT INTO public.student_transfer_events (institution_id, transfer_request_id, actor_user_id, action)
    VALUES (p_tenant, v_request.transfer_request_id, p_actor, 'submitted');
    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.transfer.submit', 'student_transfer_requests',
        v_request.transfer_request_id::text, jsonb_build_object('after', to_jsonb(v_request)));
    RETURN jsonb_build_object('transfer_request_id', v_request.transfer_request_id,
        'institution_id', p_tenant, 'status', v_request.status);
END;
$$;

CREATE FUNCTION public.cancel_student_transfer(p_actor uuid, p_tenant uuid, p_request uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_student uuid; v_request public.student_transfer_requests;
BEGIN
    v_student := public.assert_transfer_student(p_actor, p_tenant, 'transfers.request');
    SELECT * INTO v_request FROM public.student_transfer_requests
    WHERE transfer_request_id = p_request AND institution_id = p_tenant AND student_id = v_student
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer request not found' USING ERRCODE = 'P0002';
    END IF;
    IF v_request.status NOT IN ('submitted', 'under_review') THEN
        RAISE EXCEPTION 'This transfer request is already closed' USING ERRCODE = 'P1101';
    END IF;
    UPDATE public.student_transfer_requests
    SET status = 'cancelled', cancelled_at = now(), updated_at = now()
    WHERE transfer_request_id = p_request;
    INSERT INTO public.student_transfer_events (institution_id, transfer_request_id, actor_user_id, action)
    VALUES (p_tenant, p_request, p_actor, 'cancelled');
    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.transfer.cancel', 'student_transfer_requests', p_request::text,
        jsonb_build_object('before_status', v_request.status));
    RETURN jsonb_build_object('transfer_request_id', p_request, 'institution_id', p_tenant,
        'status', 'cancelled');
END;
$$;

-- SOURCE review.sql sha256=feebdb9cc23a2b56dbfc007b57808a6b1f142a48422e0bdeeb5f330187ea7bf7
-- Administrators see every request; a Head of Department sees requests into
-- the departments they currently head. Everyone else receives can_review=false.
CREATE FUNCTION public.read_transfer_reviews(p_actor uuid, p_tenant uuid, p_open_only boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_admin boolean; v_departments uuid[];
BEGIN
    PERFORM public.assert_transfer_backend();
    v_admin := public.transfer_admin_allowed(p_actor, p_tenant, 'transfers.read');
    v_departments := public.transfer_hod_departments(p_actor, p_tenant);
    IF NOT v_admin AND cardinality(v_departments) = 0 THEN
        RETURN jsonb_build_object('institution_id', p_tenant, 'can_review', false,
            'can_decide', false, 'reviewer_role', NULL, 'departments', '[]'::jsonb,
            'requests', '[]'::jsonb);
    END IF;
    RETURN jsonb_build_object(
        'institution_id', p_tenant, 'can_review', true,
        'can_decide', cardinality(v_departments) > 0
            OR public.transfer_admin_allowed(p_actor, p_tenant, 'transfers.approve'),
        'reviewer_role', CASE WHEN v_admin THEN 'admin' ELSE 'hod' END,
        'departments', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'department_id', d.department_id, 'name', d.name) ORDER BY d.name), '[]'::jsonb)
            FROM public.departments d
            WHERE d.institution_id = p_tenant AND d.department_id = ANY (v_departments)
        ),
        'requests', public.transfer_requests_json(
            p_tenant, NULL, CASE WHEN v_admin THEN NULL ELSE v_departments END, p_open_only)
    );
END;
$$;

-- start_review, reject or approve one open request. Approval is atomic: it
-- re-validates the placement, seat and term, keeps the previous registration
-- and enrolled subjects on the request, then reassigns the registration so the
-- student registers subjects again in the new section.
CREATE FUNCTION public.decide_student_transfer(
    p_actor uuid, p_tenant uuid, p_request uuid, p_action text, p_comment text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_request public.student_transfer_requests; v_registration public.student_semester_registrations;
    v_role text; v_enrollments jsonb; v_status text;
    v_comment text := NULLIF(btrim(COALESCE(p_comment, '')), '');
BEGIN
    PERFORM public.assert_transfer_backend();
    IF p_action IS NULL OR p_action NOT IN ('start_review', 'approve', 'reject') THEN
        RAISE EXCEPTION 'Unknown transfer action' USING ERRCODE = '22023';
    END IF;
    IF length(v_comment) > 2000 THEN
        RAISE EXCEPTION 'Comments are limited to 2000 characters' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:' || p_tenant::text, 0));
    SELECT * INTO v_request FROM public.student_transfer_requests
    WHERE transfer_request_id = p_request AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer request not found' USING ERRCODE = 'P0002';
    END IF;
    IF public.transfer_admin_allowed(p_actor, p_tenant, 'transfers.approve') THEN
        v_role := 'admin';
    ELSIF v_request.to_department_id = ANY (public.transfer_hod_departments(p_actor, p_tenant)) THEN
        v_role := 'hod';
    ELSE
        RAISE EXCEPTION 'Only an administrator or the receiving department HOD can decide this request'
            USING ERRCODE = '42501';
    END IF;
    IF v_request.status NOT IN ('submitted', 'under_review') THEN
        RAISE EXCEPTION 'This transfer request is already closed' USING ERRCODE = 'P1101';
    END IF;

    IF p_action = 'start_review' THEN
        IF v_request.status = 'submitted' THEN
            UPDATE public.student_transfer_requests
            SET status = 'under_review', review_started_by = p_actor,
                review_started_at = now(), updated_at = now()
            WHERE transfer_request_id = p_request;
            INSERT INTO public.student_transfer_events
                (institution_id, transfer_request_id, actor_user_id, action, comment)
            VALUES (p_tenant, p_request, p_actor, 'review_started', v_comment);
        END IF;
        v_status := 'under_review';
    ELSIF p_action = 'reject' THEN
        IF v_comment IS NULL THEN
            RAISE EXCEPTION 'A rejection reason is required' USING ERRCODE = 'P1109';
        END IF;
        UPDATE public.student_transfer_requests
        SET status = 'rejected', decided_by = p_actor, decided_at = now(), decided_as = v_role,
            decision_comment = v_comment, updated_at = now()
        WHERE transfer_request_id = p_request;
        INSERT INTO public.student_transfer_events
            (institution_id, transfer_request_id, actor_user_id, action, comment)
        VALUES (p_tenant, p_request, p_actor, 'rejected', v_comment);
        v_status := 'rejected';
    ELSE
        SELECT * INTO v_registration FROM public.student_semester_registrations
        WHERE semester_registration_id = v_request.semester_registration_id
          AND institution_id = p_tenant
        FOR UPDATE;
        IF NOT FOUND OR v_registration.student_id <> v_request.student_id
           OR v_registration.academic_section_id <> v_request.from_section_id
           OR v_registration.semester_registration_id IS DISTINCT FROM
              public.transfer_current_registration(v_request.student_id, p_tenant) THEN
            RAISE EXCEPTION 'The student''s section changed after this request was submitted'
                USING ERRCODE = 'P1102';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.semesters WHERE semester_id = v_registration.semester_id
                       AND is_active AND end_date >= current_date) THEN
            RAISE EXCEPTION 'The current term is closed' USING ERRCODE = 'P1103';
        END IF;
        IF public.transfer_target_type(v_request.from_section_id, v_request.to_section_id, p_tenant)
           IS DISTINCT FROM v_request.transfer_type THEN
            RAISE EXCEPTION 'The requested section is unavailable' USING ERRCODE = 'P1104';
        END IF;
        IF NOT public.transfer_section_has_seat(v_request.to_section_id) THEN
            RAISE EXCEPTION 'The requested section is full' USING ERRCODE = 'P1105';
        END IF;
        SELECT COALESCE(jsonb_agg(soe.subject_snapshot || jsonb_build_object(
                'academic_offering_id', soe.academic_offering_id, 'enrolled_at', soe.enrolled_at)
            ORDER BY soe.enrolled_at, soe.offering_enrollment_id), '[]'::jsonb)
        INTO v_enrollments
        FROM public.student_offering_enrollments soe
        WHERE soe.semester_registration_id = v_registration.semester_registration_id;
        -- Offerings belong to the old section, so they cannot follow the student.
        DELETE FROM public.student_offering_enrollments
        WHERE semester_registration_id = v_registration.semester_registration_id;
        UPDATE public.student_semester_registrations
        SET academic_section_id = v_request.to_section_id, status = 'assigned',
            selected_option_ids = '{}'::uuid[], registered_at = NULL, assigned_at = now()
        WHERE semester_registration_id = v_registration.semester_registration_id;
        UPDATE public.student_transfer_requests
        SET status = 'approved', decided_by = p_actor, decided_at = now(), decided_as = v_role,
            decision_comment = v_comment, previous_registration = to_jsonb(v_registration),
            previous_enrollments = v_enrollments, updated_at = now()
        WHERE transfer_request_id = p_request;
        INSERT INTO public.student_transfer_events
            (institution_id, transfer_request_id, actor_user_id, action, comment)
        VALUES (p_tenant, p_request, p_actor, 'approved', v_comment);
        v_status := 'approved';
    END IF;

    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.transfer.' || p_action, 'student_transfer_requests',
        p_request::text, jsonb_build_object('decided_as', v_role, 'before_status', v_request.status,
            'after_status', v_status, 'comment', v_comment));
    RETURN jsonb_build_object('transfer_request_id', p_request, 'institution_id', p_tenant,
        'status', v_status);
END;
$$;

-- SOURCE department_heads.sql sha256=3f2b740e66caadcbe7f943b25e83455b6b6e1cbd8abe25b2def6a018b0137d7a
-- Current Heads of Department plus the faculty members who may be appointed.
CREATE FUNCTION public.read_department_heads(p_actor uuid, p_tenant uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM public.assert_transfer_backend();
    IF NOT public.transfer_admin_allowed(p_actor, p_tenant, 'departments.read') THEN
        RAISE EXCEPTION 'Administrator permission required' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object(
        'institution_id', p_tenant,
        'heads', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'department_id', h.department_id, 'faculty_user_id', h.faculty_user_id,
                'name', COALESCE(NULLIF(btrim(u.display_name), ''),
                    NULLIF(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email),
                'email', u.email, 'assigned_at', h.assigned_at,
                'is_active_faculty', public.transfer_is_active_faculty(h.faculty_user_id, p_tenant)
            ) ORDER BY h.department_id), '[]'::jsonb)
            FROM public.department_heads h
            JOIN public.users u ON u.id = h.faculty_user_id
            WHERE h.institution_id = p_tenant AND h.ended_at IS NULL
        ),
        'faculty', (
            SELECT COALESCE(jsonb_agg(member ORDER BY member->>'name', member->>'user_id'), '[]'::jsonb)
            FROM (
                SELECT DISTINCT jsonb_build_object(
                    'user_id', u.id,
                    'name', COALESCE(NULLIF(btrim(u.display_name), ''),
                        NULLIF(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email),
                    'email', u.email
                ) AS member
                FROM public.users u
                JOIN public.user_roles ur ON ur.user_id = u.id
                JOIN public.roles r ON r.id = ur.role_id
                WHERE r.name = 'faculty' AND ur.scope_type = 'institution' AND ur.scope_id = p_tenant
                  AND public.transfer_is_active_faculty(u.id, p_tenant)
            ) faculty_members
        )
    );
END;
$$;

-- Appoint (p_faculty) or remove (NULL) the department's Head of Department.
-- The previous appointment is ended, never deleted.
CREATE FUNCTION public.assign_department_head(
    p_actor uuid, p_tenant uuid, p_department uuid, p_faculty uuid
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_department public.departments; v_current public.department_heads;
BEGIN
    PERFORM public.assert_transfer_backend();
    IF NOT public.transfer_admin_allowed(p_actor, p_tenant, 'departments.manage') THEN
        RAISE EXCEPTION 'Administrator permission required' USING ERRCODE = '42501';
    END IF;
    SELECT * INTO v_department FROM public.departments
    WHERE department_id = p_department AND institution_id = p_tenant
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Department not found' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_current FROM public.department_heads
    WHERE department_id = p_department AND institution_id = p_tenant AND ended_at IS NULL
    FOR UPDATE;
    IF p_faculty IS NOT NULL THEN
        IF NOT v_department.is_active OR NOT public.transfer_is_active_faculty(p_faculty, p_tenant) THEN
            RAISE EXCEPTION 'Choose an active faculty member for an active department'
                USING ERRCODE = 'P1110';
        END IF;
        IF v_current.faculty_user_id = p_faculty THEN
            RETURN jsonb_build_object('department_id', p_department, 'faculty_user_id', p_faculty,
                'institution_id', p_tenant);
        END IF;
    ELSIF v_current.department_head_id IS NULL THEN
        RETURN jsonb_build_object('department_id', p_department, 'faculty_user_id', NULL,
            'institution_id', p_tenant);
    END IF;
    IF v_current.department_head_id IS NOT NULL THEN
        UPDATE public.department_heads SET ended_at = now(), ended_by = p_actor
        WHERE department_head_id = v_current.department_head_id;
    END IF;
    IF p_faculty IS NOT NULL THEN
        INSERT INTO public.department_heads (institution_id, department_id, faculty_user_id, assigned_by)
        VALUES (p_tenant, p_department, p_faculty, p_actor);
    END IF;
    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.department.head', 'department_heads', p_department::text,
        jsonb_build_object('before', v_current.faculty_user_id, 'after', p_faculty));
    RETURN jsonb_build_object('department_id', p_department, 'faculty_user_id', p_faculty,
        'institution_id', p_tenant);
END;
$$;

-- SOURCE assignment_guard.sql sha256=0d536cd914ae84917978856d380b9d8763b2d2ef7561a59458b9e611f73341d5
-- Section assignment previously refused any student with a registration in
-- another batch. After an approved program transfer the student's earlier
-- terms stay in the old batch, which would block every later assignment in the
-- new one. Compare against the student's current placement instead; moving a
-- student between batches still requires the transfer workflow.
CREATE OR REPLACE FUNCTION public.assign_student_semester(p_actor uuid,p_tenant uuid,p_student uuid,p_section uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE section_row jsonb; result public.student_semester_registrations; student_row record;
BEGIN
    PERFORM public.assert_academic_foundation_actor(p_actor,p_tenant,'courses');
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.update');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT * INTO student_row FROM public.students
    WHERE student_id=p_student AND institution_id=p_tenant FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student not found' USING ERRCODE='P0002'; END IF;
    IF student_row.approval_status<>'approved' OR NOT student_row.is_active OR student_row.status<>'active' THEN
        RAISE EXCEPTION 'Assign only approved active students' USING ERRCODE='23514';
    END IF;
    section_row:=public.academic_structure_parent('academic_sections',p_section,p_tenant);
    IF EXISTS(SELECT 1 FROM public.student_semester_registrations reg
        JOIN public.academic_sections sec USING(academic_section_id)
        WHERE reg.semester_registration_id=public.transfer_current_registration(p_student,p_tenant)
          AND sec.admission_cohort_id<>(section_row->>'admission_cohort_id')::uuid) THEN
        RAISE EXCEPTION 'Student already belongs to another batch; a transfer requires a separate workflow' USING ERRCODE='23514';
    END IF;
    SELECT * INTO result FROM public.student_semester_registrations
    WHERE student_id=p_student AND semester_id=(section_row->>'semester_id')::uuid FOR UPDATE;
    IF FOUND THEN
        IF result.academic_section_id=p_section THEN RETURN to_jsonb(result); END IF;
        IF result.status='registered' THEN
            RAISE EXCEPTION 'Completed registration cannot be reassigned' USING ERRCODE='P1004';
        END IF;
    END IF;
    IF (section_row->>'capacity') IS NOT NULL AND
       (SELECT count(*) FROM public.student_semester_registrations WHERE academic_section_id=p_section)
           >=(section_row->>'capacity')::integer THEN
        RAISE EXCEPTION 'Section capacity reached' USING ERRCODE='P1002';
    END IF;
    INSERT INTO public.student_semester_registrations(institution_id,student_id,academic_section_id,semester_id)
    VALUES(p_tenant,p_student,p_section,(section_row->>'semester_id')::uuid)
    ON CONFLICT(student_id,semester_id) DO UPDATE SET academic_section_id=EXCLUDED.academic_section_id,assigned_at=now()
    RETURNING * INTO result;
    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data)
    VALUES(p_actor,p_tenant,'academic.semester.assign','student_semester_registrations',result.semester_registration_id::text,
        jsonb_build_object('after',to_jsonb(result)));
    RETURN to_jsonb(result);
END;
$$;

-- SOURCE security.sql sha256=fca1352a09810cc5a68e1eb55de628bc01681c8c70ca569accca77d29a427577
DO $$
DECLARE relation_name text;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY['department_heads', 'student_transfer_requests',
        'student_transfer_events'] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres', relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role',
            relation_name);
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role', relation_name);
    END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION
    public.assert_transfer_backend(),
    public.transfer_admin_allowed(uuid, uuid, text),
    public.transfer_is_active_faculty(uuid, uuid),
    public.transfer_hod_departments(uuid, uuid),
    public.assert_transfer_student(uuid, uuid, text),
    public.transfer_current_registration(uuid, uuid),
    public.transfer_section_json(uuid, uuid),
    public.transfer_target_type(uuid, uuid, uuid),
    public.transfer_section_has_seat(uuid),
    public.transfer_requests_json(uuid, uuid, uuid[], boolean),
    public.read_student_transfers(uuid, uuid),
    public.submit_student_transfer(uuid, uuid, uuid, text),
    public.cancel_student_transfer(uuid, uuid, uuid),
    public.read_transfer_reviews(uuid, uuid, boolean),
    public.decide_student_transfer(uuid, uuid, uuid, text, text),
    public.read_department_heads(uuid, uuid),
    public.assign_department_head(uuid, uuid, uuid, uuid)
FROM PUBLIC, anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION
    public.read_student_transfers(uuid, uuid),
    public.submit_student_transfer(uuid, uuid, uuid, text),
    public.cancel_student_transfer(uuid, uuid, uuid),
    public.read_transfer_reviews(uuid, uuid, boolean),
    public.decide_student_transfer(uuid, uuid, uuid, text, text),
    public.read_department_heads(uuid, uuid),
    public.assign_department_head(uuid, uuid, uuid, uuid)
TO service_role;

NOTIFY pgrst, 'reload schema';
COMMIT;
